### Suggested new tool

```
namespace hr {
  // Rejects or flags candidates whose education records match a given pattern
  type reject_candidates_by_education = (_: {
    // The exact string or regex to match in the education field
    education_pattern: string,  
    // The action to take (e.g., "reject", "flag", "notify_hr")
    action: string,           
    // Optional: include a message or reason that will be stored in the candidate’s file
    reject_reason?: string    
  }) => any;
}
