**Draft SQL Script to Drop All Tables in the `inventory` Database**

```sql
/* --------------------------------------------------
   1. Generate a list of all tables in the `inventory` database
   2. Build a dynamic DROP TABLE statement for each table
   3. Execute the generated statements
 -------------------------------------------------- */

SET @@TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; -- optional, but faster

-- Step 1: Create a temporary table to hold the SQL drop commands
CREATE TEMPORARY TABLE drop_cmds (cmd VARCHAR(1000));

-- Step 2: Populate the temp table with DROP statements
INSERT INTO drop_cmds (cmd)
SELECT
    CONCAT('DROP TABLE IF EXISTS `', table_schema, '`.`', table_name, '`;')
FROM
    information_schema.tables
WHERE
    table_schema = 'inventory'        -- target database
    AND table_type = 'BASE TABLE';    -- exclude views, etc.

-- Step 3: Execute each generated command
SELECT
    mysql_stmt_execute(stmt) AS `Result`
FROM
    (SELECT
        CONCAT('PREPARE stmt FROM "', cmd, '";') AS prepare_sql,
        CONCAT('EXECUTE stmt;') AS exec_sql,
        CONCAT('DEALLOCATE PREPARE stmt;') AS dealloc_sql
    FROM drop_cmds) AS derived
JOIN (SELECT '' AS dummy) AS dummy;   -- dummy join for CROSS JOIN semantics

/* Alternatively, if you prefer a stored procedure for simplicity: */

DELIMITER //

CREATE PROCEDURE drop_all_inventory_tables()
BEGIN
    DECLARE finished INT DEFAULT 0;
    DECLARE tbl_name VARCHAR(255);
    DECLARE cur CURSOR FOR
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = 'inventory' AND table_type = 'BASE TABLE';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = 1;

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO tbl_name;
        IF finished THEN
            LEAVE read_loop;
        END IF;
        SET @sql = CONCAT('DROP TABLE IF EXISTS `inventory`.`', tbl_name, '`;');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END LOOP;
    CLOSE cur;
END //

DELIMITER ;

/* Run the procedure */
CALL drop_all_inventory_tables();
```

